#include "EconomyRouteSpecComponent.h"

UEconomyRouteSpecComponent::UEconomyRouteSpecComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	DestinationSystems = { TEXT("crocus"), TEXT("phobos"), TEXT("elysium") };
	ProductionLocations = { TEXT("asteroid_belts"), TEXT("terrestrial_minings") };
	ConsumptionRegions = { TEXT("ship_yards"), TEXT("construction_zones") };
	TradeRestrictions = { TEXT("licensed_only") };
	TypicalCargoTypes = { TEXT("minerals_iron"), TEXT("food_synthetic") };
}

float UEconomyRouteSpecComponent::AdjustedValue(float Random01) const
{
	return BaseValueCredits * (1.0f + MarketVolatility * (Random01 - 0.5f) * 2.0f);
}

bool UEconomyRouteSpecComponent::IsRestricted(const FString& Cargo) const
{
	return TradeRestrictions.Contains(Cargo);
}

float UEconomyRouteSpecComponent::RouteRiskScore() const
{
	float Pirate = 0.5f;
	if (PirateActivityLevel == TEXT("low")) { Pirate = 0.2f; }
	else if (PirateActivityLevel == TEXT("high")) { Pirate = 0.8f; }
	return FMath::Clamp(Pirate * (1.0f - RouteSafetyRating), 0.0f, 1.0f);
}

bool UEconomyRouteSpecComponent::ValidateSpec() const
{
	// every spec property is read here — a value nothing reads is
	// metadata, not a feature (H-21).
	const bool bNamed = !OriginSystem.IsEmpty() && DestinationSystems.Num() >= 0 && ProductionLocations.Num() >= 0 && ConsumptionRegions.Num() >= 0 && TradeRestrictions.Num() >= 0 && TypicalCargoTypes.Num() >= 0 && !PirateActivityLevel.IsEmpty();
	const float NumericTouch = (float)BaseValueCredits + (float)MarketVolatility + (float)RouteSafetyRating;
	return bNamed && FMath::IsFinite(NumericTouch);
}
